#!/usr/bin/env bash
# run1.sh NAME "EVENTS" — rel47: reverse l3mtcp, 3 lb paths (A 50.1 tls, B 51.1 reality with its own
# breakable target in netns tgt$LAB_ID, C 52.1 both), crowd + call + game + iperf down8. PLAIN=1: all tls.
set -u
NAME=$1; export P3_EV="$2"; D=/opt/hs2lab/r47
L=/opt/hs2lab/smuxwin/labsrc2/hs2-src/lab
export P3_OUT=$D/res/$NAME; rm -rf $P3_OUT; mkdir -p $P3_OUT
COMMON="HS2_SHAPE_FAST=1 HS2_SHAPE_SMALL=1 HS2_L3_LANE=1 HS2_HEAVY_BACKLOG=1 HS2_L3_DUP=1 HS2_MCONN=lite HS2_FAST_LINK=1 HS2_MCONN_BATCH=1 HS2_SHAPE_BULK=1 HS2_QUIET_IDLE=1 HS2_TLS_RESUME=1 HS2_AUTH_PAD=1 HS2_COVER_NGINX=1 HS2_MCONN_DEADLINE_FIX=1 HS2_MCONN_CLOSE_HS=1 HS2_LB_AUTO2=1 HS2_MCONN_CALL=1 HS2_MCONN_CALL_AVOID=1 HS2_MCONN_STRIPE=8 HS2_LB_JUDGE_DATA=1 HS2_LB_FAST_VERDICT=1 HS2_LB_RESCUE=1 HS2_LB_RESCUE_CALLFREE=1 HS2_LB_CALL_LATE=1 HS2_LB_FLAP_PEN=1 HS2_LINK_SPREAD_LOG=1"
IRP="HS2_SMUX_AUTOWIN=1 HS2_SMUX_AUTOWIN_REL=1 HS2_SMUX_AUTOWIN_SHARE_MB=32 HS2_STRIPE_AW_SOLO=1 HS2_STRIPE_AW_HEAVY=2 HS2_LB_FAST_RECOVER=1 HS2_LB_START_GRACE_S=20"
KHP="HS2_SMUX_AUTOWIN=1 HS2_SMUX_AUTOWIN_REL=1 HS2_SMUX_AUTOWIN_SHARE_MB=32 HS2_MCONN_STRIPE_JUMP_MS=1500 HS2_LB_FAST_RECOVER=1 HS2_LB_START_GRACE_S=20 HS2_LB_FILL_PCT=25 HS2_LB_SPARE_PER_ROUND=3 HS2_LB_REC_CONFIRM=1"
export KHAREJ_EXTRA="\"max_links\":150,\"min_links\":100,"
export HOME=/root GOPATH=/root/go PATH=$PATH:/usr/local/go/bin MODE=l3mtcp EMU=kernel RATE=1000mbit DELAY=37ms QUEUE=100ms
export T=${T:-45s} BULK=0 CALL=2mbit GAME=1 MIN_LINKS=100 MAX_LINKS=150 CROWD=3000 REVERSE=1 NOWARM=1 WORKDIR=/tmp/r47w PATHS=3 LB_MODE=auto LOSS=0.01 KILL_AT=${KILL_AT:-0}
env BIN=$D/ir.sh BIN_KH=$D/kh.sh IR_ENV="${XENV:-} $COMMON HS2_LINK_PROBATION=1 HS2_PARTIAL_REFILL=1 HS2_PICK_LANE=on HS2_QUEUE_CTL_UP=1 $IRP" KH_ENV="${XENV:-} $COMMON HS2_QUEUE_CTL=1 $KHP" HEAVY=down HEAVY_P=8 LOGDIR=$P3_OUT RUNTAG=$NAME bash $L/run.sh > $P3_OUT/run.out 2> $P3_OUT/run.err
tail -1 $P3_OUT/run.out > $P3_OUT/result.json
echo "LAB_ID=${LAB_ID:-} PLAIN=${PLAIN:-} EV=$P3_EV KILL_AT=${KILL_AT:-0}" > $P3_OUT/meta.txt
